import React, { useState } from 'react';

// Create the VirtualizedList component here
const VirtualizedList = () => {
  // Initialize scrollTop state here
  const [scrollTop, setScrollTop] = useState(0);

  // Define the list data here
  const items = Array.from({ length: 1000 }, (_, i) => `Item ${i + 1}`);

  // Define constants for item height and viewport here
  const ITEM_HEIGHT = 50;
  const VIEWPORT_HEIGHT = 400;

  // Create the calculateVisibleRange helper here
  const calculateVisibleRange = () => {
    const startIndex = Math.floor(scrollTop / ITEM_HEIGHT);
    const endIndex = Math.min(
      items.length - 1,
      Math.floor((scrollTop + VIEWPORT_HEIGHT) / ITEM_HEIGHT)
    );
    return { startIndex, endIndex };
  };

  // Create the handleScroll event handler here
  const handleScroll = (e) => {
    setScrollTop(e.target.scrollTop);
  };

  return (
    <div
      style={{ height: VIEWPORT_HEIGHT, overflowY: 'auto' }}
      onScroll={handleScroll}
    >
      <div style={{ position: 'relative', height: items.length * ITEM_HEIGHT }}>
        {/* Map over visible items here */}
      </div>
    </div>
  );
};
